<?php
require_once __DIR__.'/inc/ai/Bootstrap.php';require_once __DIR__.'/inc/saas/Nahal.php';require_once __DIR__.'/inc/saas/Providers.php';require_once __DIR__.'/inc/saas/Usage.php';require_once __DIR__.'/inc/saas/Ehsan.php';require_once __DIR__.'/inc/saas/Aria.php';require_once __DIR__.'/inc/saas/Commerce.php';require_once __DIR__.'/inc/ProjectMembers.php';require_once __DIR__.'/inc/ProjectPurchases.php';header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
if(!isUser()||!isMainAdmin())AccessControl::deny();$service=new SaaSAccounts();$nahal=new Nahal($service);$commerce=new SaaSCommerce($service);$providers=new SaaSProviders($service);$error='';$message='';
try{if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){RequestSecurity::enforce();$action=$_POST['action']??'';
if($action==='assign_project_ai')$service->assignProjectAI($_POST['pid']??'',$_POST['employees']??[],trim($_POST['reason']??''),$_POST['owner']??'',!empty($_POST['plan_id'])?ProjectPlans::find($_POST['plan_id']):null);
elseif($action==='activate_project')$service->activate($_POST['account']??'',$_POST['pid']??'',$_POST['employee']??'',!empty($_POST['enabled']));
elseif($action==='grant_employee')$service->grantEmployee($_POST['account']??'',$_POST['employee']??'',(int)($_POST['cap']??0),$_POST['reason']??'');
elseif($action==='resolve_aria')(new Aria($service))->resolve($_POST['job']??'',(int)($_POST['charge']??-1));
elseif($action==='resolve_ehsan')(new Ehsan($service))->resolve($_POST['job']??'',(int)($_POST['charge']??-1));
