?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تیم مرکزی / حساب‌ها و AI</title><link rel="stylesheet" href="/panel/assets/workspace-shell.css"><link rel="stylesheet" href="/panel/assets/saas.css?v=1"></head><body class="workspace-page"><main class="workspace-shell saas-shell"><header class="saas-top"><a href="/panel/workspace.php?central=1">← میزکار مرکزی</a><span>تیم مرکزی مارک‌شو</span></header><div class="saas-hero"><span>مدیریت اشتراک و کارمندهای هوشمند</span><h1>حساب‌ها، تعرفه‌ها و مدل‌ها</h1><p>کلیدها فقط در فضای خصوصی رمزگذاری می‌شوند. خرید مشتری، اعتبار داخلی پروژه را شارژ می‌کند؛ موجودی ارائه‌دهنده حساب جداگانه‌ای است.</p></div><?php if($error):?><p class="saas-alert error" role="alert"><?=sc_h($error)?></p><?php endif;?><?php if($message):?><p class="saas-alert" role="status"><?=sc_h($message)?></p><?php endif;?>
<div class="saas-metrics"><article><small>حساب‌های مشتری</small><strong><?=count($state['accounts']??[])?></strong></article><article><small>کردیت پروژه‌ها</small><strong><?=number_format(array_sum(array_map(static function($a){return array_sum(array_column($a['wallets']??[],'balance'));},$state['accounts']??[])))?></strong><span>دفتر اعتبار داخلی؛ معادل موجودی واقعی سرویس‌دهنده نیست.</span></article><article><small>موجودی API ارائه‌دهندگان</small><strong>تأیید نشده</strong><span>تا اتصال قرارداد API موجودی ارائه‌دهنده، عدد فرضی نمایش داده نمی‌شود.</span></article></div>
<section class="saas-card"><h2>افزودن سریع AI و کارمند به پروژهٔ موجود</h2><p>پروژه را باز کنید، کارمندها را انتخاب کنید و ثبت کنید. این تخصیص رایگانِ تیم مرکزی ثبت و حسابرسی می‌شود؛ اعتبار مصرف ایجاد نمی‌کند. دسترسی AI حساب و برای آریا دسترسی تقویم، مشترک است؛ ولی کارمند فقط در پروژهٔ انتخابی فعال می‌شود. مجوز نقش کاربران همچنان لازم است.</p><?php foreach(ProjectSelection::projects() as $item):$existing=getCurrentProject($item['id'],true);if(!$existing)continue;$mapped=$state['project_accounts'][$item['id']]??null;?><details class="saas-project"><summary><?=sc_h($item['name'])?> · <?=$mapped?'دارای حساب':'پروژهٔ قدیمی'?></summary><form method="post"><input type="hidden" name="action" value="assign_project_ai"><input type="hidden" name="pid" value="<?=sc_h($item['id'])?>"><?php if(!$mapped):?><label>ادمین اصلی موجود پروژه<select name="owner" required><option value="">انتخاب کنید</option><?php foreach($existing['users']??[] as $member):if(($member['role']??'')!=='project_admin')continue;?><option value="<?=sc_h($member['username'])?>"><?=sc_h($member['username'])?></option><?php endforeach;?></select></label><label>پلن حساب برای اتصال پروژهٔ قدیمی<select name="plan_id" required><?php foreach(getSubscriptionPlans() as $plan):if(!in_array('ai_connect',ProjectPlans::modules($plan),true))continue;?><option value="<?=sc_h($plan['id'])?>"><?=sc_h($plan['name'])?></option><?php endforeach;?></select></label><p>اشتراک یک‌ماهه با معافیت مرکزی ایجاد می‌شود؛ پروژهٔ ازقبل متصل به حساب، مدت خود را حفظ می‌کند.</p><?php endif;?><label class="saas-toggle"><input type="checkbox" name="employees[]" value="ehsan">احسان — تحلیل و گزارش</label><label class="saas-toggle"><input type="checkbox" name="employees[]" value="nahal">نهال — تولید تصویر</label><label class="saas-toggle"><input type="checkbox" name="employees[]" value="aria">آریا — برنامه‌ریزی محتوا و انتشار</label><label>دلیل تخصیص<input name="reason" maxlength="500" required></label><button>افزودن AI و کارمندهای انتخابی</button><p>پس از تخصیص، مالک پروژه از «کارمندهای من» تنظیمات کارمند را تکمیل می‌کند. مدل فعال مرکزی، اعتبار آزاد و داده‌های لازم باید موجود باشند؛ برای نهال فضای ذخیره‌سازی هم لازم است.</p></form></details><?php endforeach;?></section>
<section class="saas-card"><h2>حساب‌ها و مصرف پروژه‌ها</h2><?php foreach($state['accounts']??[] as $a):?><article class="saas-project"><h3><?=sc_h($a['owner'].' / '.$a['plan_name'])?></h3><p>پایان مشترک: <?=formatPersianDate($a['expires_at'],'Y/m/d')?> · پروژه <?=count($a['projects'])?> / <?=$a['limits']['projects']?> · نفرات <?=$a['limits']['seats']?> · حجم <?=number_format($a['limits']['storage_mb'])?> MB</p><p>نهال: ظرفیت <?=$a['employees']['nahal']??0?> · فعال در <?=count($a['active_employees']['nahal']??[])?> پروژه</p><a href="/panel/account.php?account=<?=rawurlencode($a['id'])?>">مشاهدهٔ حساب</a></article><?php endforeach;?></section>
<section class="saas-card"><h2>انتخاب پروژه، فعال‌سازی و مصرف AI</h2><p>انتخاب پروژه در این بخش، میزکار جاری را تغییر نمی‌دهد. فعال‌سازی تابع اشتراک و ظرفیت خریداری‌شدهٔ حساب است.</p><?php foreach($state['accounts']??[] as $a):foreach(array_keys($a['projects']??[]) as $pid):$project=getCurrentProject($pid,true);if(!$project)continue;$w=$a['wallets'][$pid]??[];?><details class="saas-project"><summary><?=sc_h($project['name'].' / '.$a['owner'])?></summary><p>اعتبار کل: <?=number_format($w['balance']??0)?> · آزاد: <?=number_format(($w['balance']??0)-($w['reserved']??0))?> · رزروشده: <?=number_format($w['reserved']??0)?></p><?php foreach(['ehsan'=>'احسان','nahal'=>'نهال','aria'=>'آریا'] as $employee=>$name):?><form method="post"><input type="hidden" name="account" value="<?=sc_h($a['id'])?>"><input type="hidden" name="pid" value="<?=sc_h($pid)?>"><input type="hidden" name="employee" value="<?=$employee?>"><label class="saas-toggle"><input type="checkbox" name="enabled" <?=!empty($a['active_employees'][$employee][$pid])?'checked':''?>> <?=$name?> برای این پروژه فعال باشد (ظرفیت حساب: <?=(int)($a['employees'][$employee]??0)?>)</label><button name="action" value="activate_project">ثبت <?=$name?></button></form><?php endforeach; SaaSUsage::render($state,$pid,'sc_h');?></details><?php endforeach;endforeach;?></section>
<section class="saas-card"><h2>موجودی واقعی تمام سرویس‌دهندگان</h2><p>اعتبار حساب سرویس‌دهنده بین مدل‌های همان حساب مشترک است؛ جمع‌کردن آن به‌ازای هر مدل اشتباه است. با کلید تولید معمولی، موجودی همهٔ این سرویس‌ها قابل استعلام یکسان نیست. موجودی نامعلوم، صفر محسوب نمی‌شود.</p><div class="saas-grid"><?php foreach(['openai'=>['OpenAI','https://platform.openai.com/settings/organization/billing/overview'],'anthropic'=>['Claude','https://console.anthropic.com/settings/billing'],'avalai'=>['AvalAI','https://avalai.ir/']] as $provider=>$info):$connections=0;foreach(array_merge(array_values($state['central_providers']??[]),array_values($state['image_models']??[])) as $connection)if(($connection['provider']??'')===$provider)$connections++;?><article class="saas-project"><h3><?=sc_h($info[0])?></h3><p>اتصال ثبت‌شده: <?=$connections?></p><strong>موجودی API: قابل تأیید نیست</strong><p>رابط مستند و مجوز استعلام مالی در این نصب متصل نشده است. تست مدل، موجودی را تأیید نمی‌کند.</p><a href="<?=sc_h($info[1])?>" target="_blank" rel="noopener noreferrer">استعلام موجودی از حساب رسمی سرویس‌دهنده</a></article><?php endforeach;?></div></section>
<section class="saas-card"><h2>سقف پلن‌ها و کارمند شامل اشتراک</h2><p>تغییرات برای خرید جدید است؛ حقوق خریداری‌شدهٔ حساب‌های قبلی خودکار کم نمی‌شود. قیمت و امکانات پلن از مدیریت تعرفه‌های قبلی قابل ویرایش است.</p><div class="saas-grid"><?php foreach(getSubscriptionPlans() as $plan):$limits=SaaSAccounts::planLimits($plan);?><form class="saas-project" method="post"><h3><?=sc_h($plan['name'])?></h3><input type="hidden" name="id" value="<?=sc_h($plan['id'])?>"><?php foreach(['max_projects'=>['سقف پروژه',$limits['projects']],'max_members'=>['تعداد افراد یکتا',$limits['seats']],'storage_mb'=>['حجم کل حساب MB',$limits['storage_mb']],'nahal_projects'=>['پروژهٔ مجاز نهال در پلن',$plan['nahal_projects']??0],'ehsan_projects'=>['پروژهٔ مجاز احسان در پلن',$plan['ehsan_projects']??0],'aria_projects'=>['پروژهٔ مجاز آریا در پلن',$plan['aria_projects']??0]] as $field=>$cfg):?><label><?=$cfg[0]?><input type="number" name="<?=$field?>" min="<?=in_array($field,['nahal_projects','ehsan_projects','aria_projects'],true)?0:1?>" value="<?=(int)$cfg[1]?>" required></label><?php endforeach;?><button name="action" value="plan">ثبت سقف‌ها</button></form><?php endforeach;?></div></section>
<section class="saas-card"><h2>تعرفهٔ بسته‌های ارتقا و اعتبار</h2><p>قیمت بسته می‌تواند شامل تخفیف باشد؛ مبلغ و مقدار نهایی سمت سرور در سفارش ثابت ثبت می‌شود.</p><div class="saas-grid"><?php foreach($state['catalog']??[] as $product):?><article class="saas-project"><h3><?=sc_h($product['name'])?></h3><p><?=number_format($product['price_toman'])?> تومان / <?=number_format($product['units'])?> <?=sc_h($product['kind'])?></p><code><?=sc_h($product['id'])?></code></article><?php endforeach;?></div><form method="post"><input type="hidden" name="action" value="product"><div class="saas-grid"><label>شناسهٔ ثابت بسته<input name="id" required pattern="[A-Za-z0-9_-]+"></label><label>نام بسته<input name="name" required></label><label>نوع<select name="kind"><option value="credits">کردیت AI</option><option value="projects">پروژهٔ اضافه</option><option value="seats">عضو اضافه</option><option value="storage_mb">حجم اضافه MB</option><option value="nahal">ظرفیت فعال‌سازی نهال</option><option value="ehsan">ظرفیت فعال‌سازی احسان</option><option value="aria">ظرفیت فعال‌سازی آریا</option></select></label><label>تعداد / مقدار<input type="number" name="units" min="1" required></label><label>قیمت نهایی تومان<input type="number" name="price_toman" min="1500" required></label><label class="saas-toggle"><input type="checkbox" name="enabled" checked>قابل خرید باشد</label></div><button>ثبت بسته</button></form></section>
<section class="saas-card"><h2>اتصال مرکزی OpenAI، Claude و AvalAI</h2><p>این اتصال‌ها برای موتور داخلی AI هستند. اتصال شخصی ChatGPT و اعتبار پروژه‌ها جداست. تست زیر فقط دسترسی مدل را می‌سنجد و هزینهٔ تولید ندارد؛ موجودی و تولید را تأیید نمی‌کند.</p><div class="saas-grid"><?php foreach($providers->catalog() as $r):?><article class="saas-project"><h3><?=sc_h($r['model'])?></h3><p><?=sc_h($r['provider'])?> · <?=!empty($r['probe']['success'])?'دسترسی مدل تأیید شده':'هنوز تأیید نشده'?></p><form method="post"><input type="hidden" name="id" value="<?=sc_h($r['id'])?>"><button name="action" value="probe_provider">تست دسترسی مدل</button></form></article><?php endforeach;?></div><form method="post"><input type="hidden" name="action" value="provider"><div class="saas-grid"><label>شناسهٔ اتصال<input name="id" required pattern="[A-Za-z0-9_-]+"></label><label>ارائه‌دهنده<select name="provider"><?php foreach(SaaSProviders::definitions() as $key=>$d):?><option value="<?=$key?>"><?=sc_h($d['name'])?></option><?php endforeach;?></select></label><label>شناسهٔ مدل<input name="model" required dir="ltr"></label><label>کلید API؛ خالی برای حفظ قبلی<input type="password" name="key" autocomplete="new-password"></label><label>سقف توکن خروجی<input type="number" name="max_output_tokens" min="1" max="32768" value="1024" required></label><label class="saas-toggle"><input type="checkbox" name="enabled" checked>فعال باشد</label></div><label>معرفی قابلیت و کاربرد مدل<input name="description" maxlength="500"></label><label class="saas-toggle"><input type="checkbox" name="ehsan_default">مدل پیش‌فرض احسان</label><label>راهنمای تخصصی احسان برای این مدل<textarea name="ehsan_instructions" maxlength="4000" rows="3"></textarea></label><label>کردیت هر اجرای احسان<input type="number" name="credits" min="1"></label><label class="saas-toggle"><input type="checkbox" name="ehsan_enabled">برای احسان قابل انتخاب باشد</label><label class="saas-toggle"><input type="checkbox" name="aria_enabled">برای آریا قابل انتخاب باشد (همان تعرفهٔ کردیت هر اجرا)</label><label class="saas-toggle"><input type="checkbox" name="aria_default">مدل پیش‌فرض آریا</label><label>راهنمای تخصصی آریا<textarea name="aria_instructions" maxlength="4000" rows="3"></textarea></label><button>ثبت امن اتصال مرکزی</button></form><p>Claude برای متن و تحلیل قابل اتصال است؛ ساخت تصویر نهال به مدل ویرایش تصویر نیاز دارد. پشتیبانی هر مدل AvalAI باید جدا بررسی شود.</p></section>
<section class="saas-card"><h2>مدل تولید تصویر نهال</h2><p>مدل باید از API ویرایش تصویر سازگار با image/edits و تصاویر مرجع پشتیبانی کند. تنظیم مدل، اثبات موفقیت اتصال یا داشتن اعتبار نیست؛ اولین اجرای واقعی رسید خودش را دارد.</p><div class="saas-grid"><?php foreach($state['image_models']??[] as $m):?><article class="saas-project"><h3><?=sc_h($m['model'])?></h3><p><?=sc_h($m['provider'])?> · <?=$m['credits']?> کردیت برای هر خروجی</p><p><?=$m['enabled']?'فعال':'متوقف'?></p><code><?=sc_h($m['id'])?></code></article><?php endforeach;?></div><form method="post"><input type="hidden" name="action" value="model"><div class="saas-grid"><label>شناسهٔ اتصال<input name="id" required pattern="[A-Za-z0-9_-]+"></label><label>ارائه‌دهنده<select name="provider"><option value="openai">OpenAI API</option><option value="avalai">AvalAI API سازگار</option></select></label><label>شناسهٔ مدل تصویر<input name="model" required dir="ltr"></label><label>کلید API؛ خالی = حفظ قبلی<input type="password" name="key" autocomplete="new-password"></label><label>تعرفهٔ هر خروجی (کردیت)<input type="number" name="credits" min="1" required></label><label class="saas-toggle"><input type="checkbox" name="enabled" checked>مدل فعال باشد</label></div><button>ذخیرهٔ امن مدل مرکزی</button></form></section>
<section class="saas-card"><h2>بررسی نتایج نامشخص</h2><p>پس از بررسی مصرف واقعی نزد ارائه‌دهنده، هزینه را بین صفر و سقف رزروشده تسویه کنید. درخواست تولید خودکار تکرار نمی‌شود.</p><?php foreach($state['image_jobs']??[] as $j):if($j['state']!=='uncertain')continue;?><form method="post"><input type="hidden" name="job" value="<?=sc_h($j['id'])?>"><p><?=sc_h($j['project'].' / '.$j['product']['name'])?> · رزرو <?=$j['credits']?> کردیت</p><label>هزینهٔ بررسی‌شده<input type="number" name="charge" min="0" max="<?=$j['credits']?>" required></label><button name="action" value="resolve">ثبت بررسی و آزادسازی باقی‌مانده</button></form><?php endforeach;?></section>
<section class="saas-card"><details><summary>انتقال پروژهٔ قدیمی با معافیت ثبت‌شدهٔ تیم مرکزی</summary><p>هیچ پروژهٔ قدیمی خودکار صاحب اعتبار یا اشتراک جدید نمی‌شود. ادمین اصلی موجود پروژه را مشخص کنید.</p><form method="post"><input type="hidden" name="action" value="adopt"><label>شناسهٔ پروژه<input name="pid" required></label><label>نام کاربری ادمین اصلی موجود<input name="owner" required></label><label>پلن<select name="plan_id"><?php foreach(getSubscriptionPlans() as $plan):?><option value="<?=sc_h($plan['id'])?>"><?=sc_h($plan['name'])?></option><?php endforeach;?></select></label><label>مدت<select name="cycle"><option value="monthly">یک ماه</option><option value="yearly">یک سال</option></select></label><button>ثبت معافیت و اتصال به حساب</button></form></details></section>
<section class="saas-card"><details><summary>ساخت حساب و پروژهٔ جدید بدون پرداخت توسط تیم</summary><form method="post"><input type="hidden" name="action" value="free_project"><label>نام پروژه<input name="project_name" required></label><label>نام کاربری مالک<input name="username" required minlength="3"></label><label>رمز اولیهٔ مالک<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><label>موبایل مالک<input name="mobile" required></label><label>پلن<select name="plan_id"><?php foreach(getSubscriptionPlans() as $plan):?><option value="<?=sc_h($plan['id'])?>"><?=sc_h($plan['name'])?></option><?php endforeach;?></select></label><button>ساخت با معافیت ثبت‌شده</button></form></details></section>
<section class="saas-card"><details><summary>تخصیص دسترسی کارمند با معافیت تیم مرکزی</summary><p>اعتبار مصرف ایجاد نمی‌شود؛ این فرم فقط ظرفیت استخدام را با دلیل ثبت‌شده افزایش می‌دهد.</p><form method="post"><input type="hidden" name="action" value="grant_employee"><label>حساب<select name="account"><?php foreach($state['accounts']??[] as $account):?><option value="<?=sc_h($account['id'])?>"><?=sc_h($account['owner'])?></option><?php endforeach;?></select></label><label>کارمند<select name="employee"><option value="ehsan">احسان</option><option value="aria">آریا</option><option value="nahal">نهال</option></select></label><label>حداقل ظرفیت مجاز فعال‌سازی در پروژه‌ها<input type="number" name="cap" min="1" max="10000" required></label><label>دلیل معافیت<input name="reason" maxlength="500" required></label><button>ثبت تخصیص با معافیت</button></form></details></section><section class="saas-card"><h2>مصرف‌های نامشخص احسان</h2><?php foreach($state['ehsan_jobs']??[] as $j):if($j['state']!=='uncertain')continue;?><form method="post"><input type="hidden" name="job" value="<?=sc_h($j['id'])?>"><p><?=sc_h($j['project'])?> · رزرو <?=$j['credits']?> کردیت</p><input type="number" name="charge" min="0" max="<?=$j['credits']?>" required><button name="action" value="resolve_ehsan">ثبت بررسی مصرف واقعی</button></form><?php endforeach;?></section><section class="saas-card"><h2>مصرف‌های نامشخص آریا</h2><?php foreach($state['aria_jobs']??[] as $j):if($j['state']!=='uncertain')continue;?><form method="post"><input type="hidden" name="job" value="<?=sc_h($j['id'])?>"><p><?=sc_h($j['project'])?> · رزرو <?=$j['credits']?> کردیت</p><input type="number" name="charge" min="0" max="<?=$j['credits']?>" required><button name="action" value="resolve_aria">ثبت بررسی مصرف واقعی</button></form><?php endforeach;?></section><section class="saas-card"><h2>تاریخچهٔ کنترل حساب‌ها</h2><?php foreach(array_slice(array_reverse($state['audit']??[]),0,60) as $event):?><p><?=formatPersianDate($event['at'],'Y/m/d H:i')?> · <?=sc_h($event['action'])?> · <?=sc_h($event['account']??'')?></p><?php endforeach;?></section></main></body></html>
